VALUES ('TensorLBM', 'm18101 XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE', 18151, 4, $json${"verdict": "L4 confirmed (with two non-blocking process/limitation notes)", "audited_mission": 18101, "audited_commit": "f2f53bd5 (TensorLBM, branch agent/m18101; not yet merged to /root/tensor-ecosystem/TensorLBM main)", "impl_files": ["/root/tp-agent/work/m18101/src/tensorlbm/multiphase.py", "/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/run_xval.py", "/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/xval_lib.py", "/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/make_report.py", "/root/tp-agent/work/m18101/tests/test_xval_mcmp_cross_force.py"], "impl_pointers": {"kernel": "src/tensorlbm/multiphase.py:534 sc_two_component_force (standard/edm)", "solver_call": "src/tensorlbm/multiphase.py:788 collide_sc_two_component calls sc_two_component_force", "slab_harness": "src/tensorlbm/mcmp_verification.py:670 simulate_planar_slab (time-marches collide+stream)", "references": "xval/.../xval_lib.py:77 oss_force (forward gather), :129 symbol_ratio S(k), :105/:116 spectral_grad/spectral_force"}, "entry": "/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/run_xval.py", "run_artifacts": ["/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/artifacts/summary.json", "/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/artifacts/slab_cases.jsonl", "/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/artifacts/fields.npz", "/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/artifacts/fig_xval.png", "/root/tp-agent/work/m18101/xval/XVAL-LBM-MCMP-TWO-COMPONENT-CROSS-FORCE/REPORT.md", "/root/tp-agent/work/m18151/artifacts/m18101_rerun_slab_cases.json", "/root/tp-agent/work/m18151/docs/audit_m18101/fig_reproduction.png"], "integration_callers": ["collide_sc_two_component: production D2Q9 MCMP path, src/tensorlbm/multiphase.py:7